import sympy

def build_instance(rng):
    sum_value = rng.randint(-10, 10)
    difference_value = rng.randint(-10, 10)
    left_x = rng.randint(-5, 5)
    right_x = rng.randint(6, 10)
    left_y = rng.randint(-5, 5)
    right_y = rng.randint(6, 10)
    x, y = sympy.symbols('x y')
    equations = [x + y - sum_value, x - y - difference_value]
    solutions = sympy.solve(equations, (x, y))
    x_solution = solutions[x]
    y_solution = solutions[y]
    if x_solution.is_integer and left_x <= x_solution <= right_x and y_solution.is_integer and (left_y <= y_solution <= right_y):
        answer = [(x_solution, y_solution)]
    else:
        answer = []
    check = [(x_solution, y_solution) for x_solution in range(left_x, right_x + 1) for y_solution in range(left_y, right_y + 1) if x_solution + y_solution == sum_value and x_solution - y_solution == difference_value]
    parameters = {'sum': sum_value, 'difference': difference_value, 'left_x': left_x, 'right_x': right_x, 'left_y': left_y, 'right_y': right_y}
    return (parameters, answer, check)



