    discriminant = coefficient1 ** 2 - 4 * coefficient2
    if discriminant < 0:
        answer = set()
    else:
        sqrt_discriminant = int(discriminant ** 0.5)
        if sqrt_discriminant ** 2 == discriminant:
            root1 = (coefficient1 + sqrt_discriminant) // 2
            root2 = (coefficient1 - sqrt_discriminant) // 2
            if 0 < root1 < modulus and 0 < root2 < modulus:
                answer = {root1, root2}
            elif 0 < root1 < modulus:
                answer = {root1}
            elif 0 < root2 < modulus:
                answer = {root2}
            else:
